class Solution {
public:
    int smallestFactorization(int a) {
        if (a < 10) {
            return a;
        }
        vector<int> digits;
        for (int digit = 9; digit >= 2; --digit) {
            while (a % digit == 0) {
                digits.push_back(digit);
                a /= digit;
            }
        }
        if (a != 1) {
            return 0;
        }
        long long result = 0;
        for (auto it = digits.rbegin(); it != digits.rend(); ++it) {
            result = result * 10 + *it;
            if (result > INT_MAX) {
                return 0;
            }
        }
        return static_cast<int>(result);
    }
};
